 "content": "from collections import defaultdict


def transform(grid):
    """Copy each patterned rectangular frame's interior motif to same-size frames."""
    h, w = len(grid), len(grid[0])
    positions = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                positions[grid[r][c]].append((r, c))

    frames = []
    for color, cells in positions.items():
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        # A frame has an unbroken perimeter of its own color. Interior pixels
        # may be sparse, and therefore belong to this same color's bbox.
        if not all(grid[r0][c] == color and grid[r1][c] == color
                   for c in range(c0, c1 + 1)):
            continue
        if not all(grid[r][c0] == color and grid[r][c1] == color
                   for r in range(r0, r1 + 1)):
            continue
        mask = [[grid[r][c] == color for c in range(r0 + 1, r1)]
                for r in range(c0 + 1, c1)]
        # The preceding comprehension is transposed; construct rows explicitly.
        mask = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                for r in range(r0 + 1, r1)]
        frames.append({"color": color, "r0": r0, "r1": r1,
                       "c0": c0, "c1": c1, "mask": mask,
                       "shape": (r1 - r0 - 1, c1 - c0 - 1)})

    groups = defaultdict(list)
    for frame in frames:
        groups[frame["shape"]].append(frame)

    out = [row[:] for row in grid]
    for group in groups.values():
        patterned = [frame for frame in group if any(any(row) for row in frame["mask"])]
        if not patterned:
            continue
        # In these puzzles a single frame in a size-group carries the motif.
        # Keep existing patterned frames and stamp its occupancy into peers.
        source = max(patterned, key=lambda frame: sum(map(sum, frame["mask"])))
        for frame in group:
            if frame is source:
                continue
            for dr, row in enumerate(source["mask"]):
                for dc, filled in enumerate(row):
                    out[frame["r0"] + 1 + dr][frame["c0"] + 1 + dc] = (
                        frame["color"] if filled else 0
                    )
    return out
"
}

